              "kind": "text",
              "text": "If a preposition (in/for/about etc.) is followed by a verb, the verb ends in **-ing**:",
              "vi": "Nếu một giới từ (in/for/about ...) được theo sau bởi một động từ, động từ đó có đuôi **-ing**:"
